SELECT * FROM (
SELECT L.PROJECT_CODE, L.SCM_SITE_ID, L.ITEM_ID, L.INCOTERMS, L.YYYYMMDD, L.QTY AMT_LOC, R.QTY AMT_KRW, P.QTY RTF,
       ROUND(L.QTY/P.QTY,3) LOC_PRICE, ROUND(R.QTY/P.QTY,3) KRW_PRICE, ROUND(L.QTY/P.QTY*1340,3) KRW_PRICE_AT_1340
FROM DM_PLN_SALES_PLAN_RESULT L
JOIN DM_PLN_SALES_PLAN_RESULT R ON R.DIVISION_ID=L.DIVISION_ID AND R.PROJECT_CODE=L.PROJECT_CODE AND R.SCM_SITE_ID=L.SCM_SITE_ID AND R.ITEM_ID=L.ITEM_ID AND R.FCST_TYPE=L.FCST_TYPE AND R.DOM_EXP=L.DOM_EXP AND R.INCOTERMS=L.INCOTERMS AND R.PLANT_SITE_ID=L.PLANT_SITE_ID AND R.YYYYMMDD=L.YYYYMMDD AND R.MEASURE='MKT_AMT_KRW'
JOIN DM_PLN_SALES_PLAN_RESULT P ON P.DIVISION_ID=L.DIVISION_ID AND P.PROJECT_CODE=L.PROJECT_CODE AND P.SCM_SITE_ID=L.SCM_SITE_ID AND P.ITEM_ID=L.ITEM_ID AND P.FCST_TYPE=L.FCST_TYPE AND P.DOM_EXP=L.DOM_EXP AND P.INCOTERMS=L.INCOTERMS AND P.PLANT_SITE_ID=L.PLANT_SITE_ID AND P.YYYYMMDD=L.YYYYMMDD AND P.MEASURE='RTF_SYS_RP'
WHERE L.DIVISION_ID='81' AND L.MEASURE='MKT_AMT_LOC' AND L.CURRENCY='USD' AND L.YYYYMMDD BETWEEN '20260901' AND '20261031' AND P.QTY<>0
ORDER BY CASE WHEN R.QTY=L.QTY THEN 0 ELSE 1 END, L.YYYYMMDD DESC) WHERE ROWNUM<=6
